package org.sleepwell.app;

import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;

public class ClipReviewPlayerTest {
    static final class Target implements ClipReviewPlayer.Target {final String key;Target(String key){this.key=key;}public String key(){return key;}public long duration(){return 1950;}}
    static final class Session implements ClipReviewPlayer.Session {final ClipReviewPlayer.Events events;int plays,pauses,closes;long at,seek;Session(ClipReviewPlayer.Events events){this.events=events;}public void play(long value){plays++;at=value;}public void pause(){pauses++;}public void seek(long value){seek=value;}public void close(){closes++;}}
    static final class Harness {final List<Session> sessions=new ArrayList<>();final List<ClipReviewPlayer.State> states=new ArrayList<>();final ClipReviewPlayer player=new ClipReviewPlayer((target,events)->{Session s=new Session(events);sessions.add(s);return s;},states::add);Harness(){player.visible(true);}Session last(){return sessions.get(sessions.size()-1);}ClipReviewPlayer.State state(){return states.get(states.size()-1);}}
    @Test public void openingDoesNotPlayUntilRealPreparationAcknowledges(){Harness h=new Harness();h.player.toggle(new Target("event:1"),600);assertEquals(0,h.last().plays);assertEquals(ClipReviewPlayer.Phase.LOADING,h.state().phase);h.last().events.ready();assertEquals(1,h.last().plays);assertEquals(600,h.last().at);h.last().events.playing();assertEquals(ClipReviewPlayer.Phase.PLAYING,h.state().phase);}
    @Test public void switchingSelectionFencesAllOldCallbacks(){Harness h=new Harness();h.player.toggle(new Target("event:1"),0);Session old=h.last();h.player.toggle(new Target("event:2"),0);old.events.ready();old.events.playing();old.events.failed("late error");assertEquals(0,old.plays);assertEquals(1,old.closes);assertEquals("event:2",h.state().key);assertEquals(ClipReviewPlayer.Phase.LOADING,h.state().phase);}
    @Test public void hiddenOrDestroyedPlayerCannotStartAfterLatePrepare(){Harness h=new Harness();h.player.toggle(new Target("event:1"),0);Session old=h.last();h.player.visible(false);old.events.ready();h.player.toggle(new Target("event:2"),0);assertEquals(1,h.sessions.size());assertEquals(0,old.plays);h.player.close();h.player.close();old.events.playing();assertEquals(1,old.closes);}
    @Test public void pauseAndFocusLossNeverAutomaticallyResume(){Harness h=new Harness();Target target=new Target("event:1");h.player.toggle(target,0);h.last().events.ready();h.last().events.playing();h.player.toggle(target,0);assertEquals(1,h.last().pauses);h.last().events.position(700);h.last().events.paused();assertEquals(1,h.last().plays);h.player.toggle(target,0);assertEquals(2,h.last().plays);assertEquals(700,h.last().at);}
    @Test public void seeksAndCompletedRestartStayWithinTheActualInterval(){Harness h=new Harness();Target target=new Target("event:1");h.player.toggle(target,9000);h.last().events.ready();assertEquals(0,h.last().at);h.last().events.playing();h.player.seek(5000);assertEquals(1950,h.last().seek);h.player.seek(-50);assertEquals(0,h.last().seek);h.last().events.ended();h.player.toggle(target,0);assertEquals(0,h.last().at);}
    @Test public void failedPrepareReleasesOwnershipAndAllowsExplicitRetry(){Harness h=new Harness();Target target=new Target("event:1");h.player.toggle(target,0);Session old=h.last();old.events.failed("Missing WAV");assertEquals(1,old.closes);assertEquals(ClipReviewPlayer.Phase.ERROR,h.state().phase);h.player.toggle(target,0);assertEquals(2,h.sessions.size());}
    @Test public void synchronousPreparationCanStillStartExactlyOnce(){List<ClipReviewPlayer.State> states=new ArrayList<>();Session[] session={null};ClipReviewPlayer p=new ClipReviewPlayer((target,events)->{session[0]=new Session(events);events.ready();return session[0];},states::add);p.visible(true);p.toggle(new Target("event:1"),0);assertEquals(1,session[0].plays);}
    @Test public void duplicatePreparedAndPlayingCallbacksCannotRestartPlayback(){Harness h=new Harness();h.player.toggle(new Target("event:1"),0);h.last().events.ready();h.last().events.playing();h.last().events.ready();h.last().events.playing();assertEquals(1,h.last().plays);}
    @Test public void explicitPauseBeforePreparationCannotAutoplayLater(){Harness h=new Harness();Target target=new Target("event:1");h.player.toggle(target,0);h.player.toggle(target,0);h.last().events.ready();assertEquals(0,h.last().plays);assertEquals(ClipReviewPlayer.Phase.PAUSED,h.state().phase);}
}
